// People (Phase 7C): who stands in each building. Regulars are fixed (keepers,
// clerks, the registrar, story characters); visitors are generated by the
// engine (src/game/engine/people.js) and rotate monthly: recruits looking for
// work, petitioners with contracts, challengers and travellers with rumours.
//
// A regular: { id, name, role, locationId, building, spot, service?, dialogue?,
//   sprite?, portrait?, lines? }
// - service: what talking offers: 'shop', 'inn', 'registrar', 'referee', 'clerk'
// - dialogue: an existing conversation (src/data/dialogue) used instead of the
//   generated talk (story characters keep their scripted scenes)
// - lines: what they say when there is nothing else to say

const reg = (locationId, building, spot, id, name, role, extra = {}) => ({ id: `${locationId}-${id}`, name, role, locationId, building, spot, ...extra });

export const REGULARS = [
  // Dunmere
  reg('dunmere', 'tavern', 'bar', 'mara', 'Mara Fen', 'Innkeeper', { dialogue: 'dunmere.innkeeper', sprite: 'npc.dunmere.innkeeper', portrait: 'portrait.story.mara' }),
  reg('dunmere', 'shop', 'counter', 'mira', 'Mira Holt', 'Shopkeeper', { service: 'shop', lines: ['Potions on the left, steel on the right, charms under glass. Touch nothing you cannot carry.'] }),
  reg('dunmere', 'arena', 'desk', 'registrar', 'Tamsin Reed', 'Registrar', { service: 'registrar', portrait: 'portrait.arena.registrar', lines: ['Names, fees and start days. The rest is up to your fighters.'] }),
  reg('dunmere', 'arena', 'ground', 'referee', 'Holt Varga', 'Referee', { service: 'referee', portrait: 'portrait.arena.referee', lines: ['I start the bouts and I stop them. Nobody argues twice.'] }),
  reg('dunmere', 'herald', 'desk', 'clerk', 'Ada Penn', 'Herald’s clerk', { service: 'clerk', lines: ['Strength, Legacy and Official. Every guild in the region, ranked and dated.'] }),
  // Greenhollow
  reg('greenhollow', 'tavern', 'bar', 'innkeeper', 'Rowe Fallow', 'Innkeeper', { service: 'inn', sprite: 'npc.greenhollow.innkeeper', portrait: 'portrait.greenhollow.innkeeper', lines: ['Welcome to the Mossy Kettle. The tea is mostly moss and the stew is mostly kettle. People stay for the company.'] }),
  reg('greenhollow', 'shop', 'counter', 'herbs', 'Wick Bramble', 'Herb seller', { service: 'shop', lines: ['Bitterroot for wounds, moss for fevers. The rest is guesswork with good manners.'] }),
  reg('greenhollow', 'arena', 'desk', 'registrar', 'Elm Carrow', 'Registrar', { service: 'registrar', portrait: 'portrait.arena.registrar', lines: ['The Thorn Cup rewards patience. Sign up if you have some.'] }),
  reg('greenhollow', 'arena', 'ground', 'referee', 'Sorrel Dane', 'Referee', { service: 'referee', portrait: 'portrait.arena.referee', lines: ['Mind the roots. The ring bites back.'] }),
  // Ironford
  reg('ironford', 'tavern', 'bar', 'barkeep', 'Mags', 'Barkeep', { service: 'inn', sprite: 'npc.ironford.barkeep', portrait: 'portrait.ironford.barkeep', lines: ['Beds upstairs, ale down here, fights outside. In that order.'] }),
  reg('ironford', 'shop', 'counter', 'trader', 'Brannoc Pike', 'Forge trader', { service: 'shop', lines: ['Ironford steel. Heavier than you want, lighter than you need.'] }),
  reg('ironford', 'arena', 'desk', 'registrar', 'Ingrid Vale', 'Registrar', { service: 'registrar', portrait: 'portrait.arena.registrar', lines: ['The Hammer Trials. Bring someone who is hard to put down.'] }),
  reg('ironford', 'arena', 'ground', 'referee', 'Gorm Halloway', 'Referee', { service: 'referee', portrait: 'portrait.arena.referee', lines: ['Clean blows only. The hammer decides the rest.'] }),
  reg('ironford', 'herald', 'desk', 'assayer', 'Petra Lund', 'Assay clerk', { service: 'clerk', lines: ['We weigh silver and guilds the same way: honestly, and in public.'] }),
  // Windmere
  reg('windmere', 'tavern', 'bar', 'innkeeper', 'Gull Tamsen', 'Innkeeper', { service: 'inn', lines: ['The Gull’s Rest. The wind keeps the guests honest and the soup cold.'] }),
  reg('windmere', 'shop', 'counter', 'supplier', 'Odo Finch', 'Courier supplier', { service: 'shop', lines: ['Maps, rope, ration tins. And blades, for the couriers who argue.'] }),
  reg('windmere', 'arena', 'desk', 'registrar', 'Brother Coll', 'Registrar', { service: 'registrar', portrait: 'portrait.arena.registrar', lines: ['The Cliff Duels take eight fighters. The wind takes whoever it likes.'] }),
  reg('windmere', 'arena', 'ground', 'referee', 'Ysa Marten', 'Referee', { service: 'referee', portrait: 'portrait.arena.referee', lines: ['Stay inside the ring. The cliff is not part of the rules.'] }),
];

export const REGULAR_BY_ID = Object.fromEntries(REGULARS.map((person) => [person.id, person]));

